    buffer.append("module ").append(moduleAttribute.moduleName).append(" {").appendLineSeparator();
    if (markSynthetics && node.type == ClassNode.Type.LOCAL) {
      appendSyntheticClassComment(cl, buffer);
    }

    buffer.append(" {").appendLineSeparator();
