   404	  private boolean processNode(ClassNode node, TextBuffer buffer) {
   405	    if (!processedNodes.add(node)) {
   406	      String failure = processingFailures.get(node);
   407	      if (failure != null) {
   408	        buffer.append(failure);
   409	        return false;
   410	      }
   411	      return true;
   412	    }
   413	
   414	    TextBuffer processingBuffer = new TextBuffer();
   415	    if (!invokeProcessors(processingBuffer, node)) {
   416	      String failure = processingBuffer.convertToStringAndAllowDataDiscard();
   417	      processingFailures.put(node, failure);
   418	      buffer.append(failure);
   419	      return false;
   420	    }
   421	
   422	    return true;
   423	  }
