   425	  private void writeClassWithReferenceAwareRetention(ClassNode node, TextBuffer buffer, int indent) {
   426	    Set<GeneratedMember> oldGeneratedMembers = generatedMembers;
   427	    Set<GeneratedMember> oldRetainedMembers = retainedMembers;
   428	    generatedMembers = collectGeneratedMembers(node);
   429	
   430	    Set<GeneratedMember> retained = new HashSet<>();
   431	    try {
   432	      while (true) {
   433	        retainedMembers = retained;
   434	        TextBuffer candidateBuffer = new TextBuffer(AVERAGE_CLASS_SIZE);
   435	        writeClassContents(node, candidateBuffer, indent);
   436	
   437	        Set<GeneratedMember> referenced = referencedGeneratedMembers(candidateBuffer);
   438	        if (!retained.addAll(referenced)) {
   439	          buffer.append(candidateBuffer);
   440	          return;
   441	        }
   442	      }
   443	    }
   444	    finally {
   445	      generatedMembers = oldGeneratedMembers;
   446	      retainedMembers = oldRetainedMembers;
   447	    }
   448	  }
