   450	  private Set<GeneratedMember> collectGeneratedMembers(ClassNode root) {
   451	    Set<GeneratedMember> result = new HashSet<>();
   452	    Set<ClassNode> visited = Collections.newSetFromMap(new IdentityHashMap<>());
   453	    collectGeneratedMembers(root, visited, result);
   454	    return result;
   455	  }
