   457	  private void collectGeneratedMembers(ClassNode node, Set<ClassNode> visited, Set<GeneratedMember> result) {
   458	    if (!visited.add(node)) {
   459	      return;
   460	    }
   461	
   462	    if (node.type != ClassNode.Type.LAMBDA) {
   463	      StructClass cl = node.classStruct;
   464	      for (StructField field : cl.getFields()) {
   465	        if (field.isSynthetic()) {
   466	          result.add(GeneratedMember.field(cl.qualifiedName, field.getName(), field.getDescriptor()));
   467	        }
   468	      }
   469	
   470	      for (StructMethod method : cl.getMethods()) {
   471	        if (method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE)) {
   472	          result.add(GeneratedMember.method(cl.qualifiedName, method.getName(), method.getDescriptor()));
   473	        }
   474	      }
   475	    }
   476	
   477	    for (ClassNode child : node.nested) {
   478	      if (child.type == ClassNode.Type.MEMBER &&
   479	        ((child.access & CodeConstants.ACC_SYNTHETIC) != 0 || child.classStruct.isSynthetic())) {
   480	        result.add(GeneratedMember.clazz(child.classStruct.qualifiedName));
   481	      }
   482	      collectGeneratedMembers(child, visited, result);
   483	    }
   484	  }
   485	
   486	  private Set<GeneratedMember> referencedGeneratedMembers(TextBuffer buffer) {
   487	    Set<GeneratedMember> result = new HashSet<>();
   488	    for (TextToken token : buffer.getTokens()) {
   489	      if (token.isDeclaration()) {
   490	        continue;
   491	      }
   492	
   493	      GeneratedMember member = null;
   494	      if (token instanceof ClassTextToken classToken) {
   495	        member = GeneratedMember.clazz(classToken.qualifiedName);
   496	      } else if (token instanceof FieldTextToken fieldToken) {
   497	        member = GeneratedMember.field(fieldToken.className, fieldToken.name, fieldToken.descriptor.descriptorString);
   498	      } else if (token instanceof MethodTextToken methodToken) {
   499	        member = GeneratedMember.method(methodToken.className, methodToken.name, methodToken.descriptor.toString());
   500	      }
   501	
   502	      if (member != null && generatedMembers.contains(member)) {
   503	        result.add(member);
   504	      }
   505	    }
   506	    return result;
   507	  }
