      JAVA_25(25),
      GROOVY("groovy", "Groovy"),
      KOTLIN("kt", "Kotlin", "kt"),
      KOTLIN_OLD("ktold", "Kotlin (old defaults)", "kt"),
      SCALA("scala", "Scala"),
      JASM("jasm", "Custom (jasm)"),
      ;

